"""Thin wrapper around the open-market stock sync CLI (vendor/bin/stockpush)."""
import os
import subprocess
import tempfile

from hbstock.models import MarketRow, Transfer, VendorError


class StockpushClient:
    def __init__(self, settings):
        self.binary = settings.stockpush_bin
        self.home = settings.stockpush_home or os.environ.get("STOCKPUSH_HOME", "")
        self.timeout = settings.stockpush_timeout

    def _run(self, *args):
        env = dict(os.environ)
        if self.home:
            env["STOCKPUSH_HOME"] = self.home
        proc = subprocess.run(
            [self.binary, *args],
            capture_output=True,
            text=True,
            encoding="utf-8",
            env=env,
            timeout=self.timeout,
        )
        if proc.returncode != 0:
            code = (proc.stderr.strip().splitlines() or ["E??"])[-1]
            raise VendorError(code, args[0])
        return proc.stdout

    def push(self, lines):
        fd, path = tempfile.mkstemp(prefix="stockpush-", suffix=".tsv")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write("\n".join(lines) + "\n")
            out = self._run("push", "--in", path)
        finally:
            os.unlink(path)
        transfer_id, _, count = out.strip().partition("\t")
        if not transfer_id.startswith("T") or not count.isdigit() or int(count) != len(lines):
            raise VendorError("E??", "push")
        return Transfer(transfer_id, int(count))

    def rows(self):
        rows = []
        for line in self._run("list").splitlines():
            parts = line.split("\t")
            if len(parts) != 4 or not parts[1].isdigit():
                continue
            sku, qty, st, transfer = parts
            rows.append(MarketRow(sku, int(qty), int(st), transfer))
        return rows

    def show(self, sku):
        out = self._run("show", sku)
        info = dict(line.split(" ", 1) for line in out.splitlines() if " " in line)
        return MarketRow(info["sku"], int(info["qty"]), int(info["st"]), info["transfer"])
"""Market-side view, read back from the vendor so it matches what shoppers see."""
from hbstock.market.feed import market_qty


class ListingService:
    def __init__(self, repo, client, settings, cache):
        self.repo = repo
        self.client = client
        self.settings = settings
        self.cache = cache

    def invalidate(self):
        self.cache.invalidate("market")

    def _rows(self):
        cached = self.cache.get("market:rows")
        if cached is None:
            cached = {row.sku: row for row in self.client.rows()}
            self.cache.put("market:rows", cached)
        return cached

    def listing(self):
        rows = self._rows()
        items = []
        for product in self.repo.products():
            row = rows.get(product.sku)
            items.append({
                "sku": product.sku,
                "name": product.name,
                "listed": row is not None,
                "market_qty": row.qty if row else 0,
                "on_sale": bool(row and row.qty > 0),
            })
        return {"items": items, "on_sale": sum(1 for i in items if i["on_sale"])}

    def product_view(self, sku):
        product = self.repo.product(sku)
        row = self._rows().get(product.sku)
        view = product.to_dict()
        view["market"] = {
            "listed": row is not None,
            "qty": row.qty if row else 0,
            "on_sale": bool(row and row.qty > 0),
        }
        return view

    def drift(self):
        """Products whose market quantity differs from what we mean to offer."""
        rows = self._rows()
        out = []
        for product in self.repo.products():
            want = market_qty(product, self.settings)
            row = rows.get(product.sku)
            have = row.qty if row else None
            if have != want and not (have is None and want == 0):
                out.append({"sku": product.sku, "ours": want, "market": have})
        return {"items": out, "count": len(out)}
"""End-to-end: catalog -> market sync -> orders and stock counts -> sync -> market listing."""
import unittest

from tests.support import VendorHome, app_with_catalog, load_catalog, order


class MarketSyncTest(unittest.TestCase):
    def setUp(self):
        self.home = VendorHome()
        self.app = app_with_catalog(self.home, load_catalog())
        first = self.app.post("/market/sync", query={"full": "1"})
        self.assertEqual(first.status, 200, first.body)
        # a day of trading
        order(self.app, "GD-104", 2, ship=True)       # 3 -> 1 left, which is the CS unit
        order(self.app, "VC-2003", 3)                   # 4 on hand, 3 reserved
        self.app.post("/products/FD-303/count", {"counted": 0})   # shelf was empty
        order(self.app, "GD-102", 1, ship=True)        # 5 -> 4
        self.app.post("/products/GD-105/receive", {"qty": 10})    # 7 -> 17
        cancelled = order(self.app, "FD-302", 2)
        self.app.post(f"/orders/{cancelled}/cancel")
        self.sync = self.app.post("/market/sync")

    def tearDown(self):
        self.home.cleanup()

    def items(self):
        resp = self.app.get("/market/listing")
        self.assertEqual(resp.status, 200, resp.body)
        return {i["sku"]: i for i in resp.body["items"]}

    def test_sync_pushes_every_changed_product(self):
        self.assertEqual(self.sync.status, 200, self.sync.body)
        self.assertEqual(
            sorted(self.sync.body["skus"]),
            ["FD-303", "GD-102", "GD-104", "GD-105", "VC-2003"],
        )

    def test_sold_out_products_are_not_on_sale(self):
        items = self.items()
        for sku in ("GD-104", "VC-2003", "FD-303"):
            self.assertFalse(items[sku]["on_sale"], f"{sku} is sold out but still on sale in the market")
            self.assertEqual(items[sku]["market_qty"], 0, sku)

    def test_products_in_stock_show_their_quantity(self):
        items = self.items()
        expected = {"GD-101": 11, "GD-102": 3, "GD-105": 16, "VC-2001": 39, "FD-302": 5, "DG-403": 7}
        for sku, qty in expected.items():
            self.assertTrue(items[sku]["on_sale"], sku)
            self.assertEqual(items[sku]["market_qty"], qty, sku)

    def test_market_matches_our_stock(self):
        drift = self.app.get("/reports/market-drift").body
        self.assertEqual(drift["items"], [], "market quantities differ from the stock we offer")

    def test_product_page_shows_market_state(self):
        body = self.app.get("/products/gd-104").body
        self.assertEqual(body["on_hand"], 1)
        self.assertFalse(body["market"]["on_sale"], "sold-out product page still says on sale")

    def test_quiet_sync_sends_nothing(self):
        again = self.app.post("/market/sync").body
        self.assertEqual(again["lines"], 0)
        self.assertIsNone(again["transfer"])

    def test_restocked_products_go_back_on_sale_with_the_next_sync(self):
        self.app.post("/products/GD-104/receive", {"qty": 6})   # 1 -> 7 on hand
        self.app.post("/products/FD-303/receive", {"qty": 4})   # 0 -> 4 on hand
        resp = self.app.post("/market/sync")
        self.assertEqual(resp.status, 200, resp.body)
        items = self.items()
        self.assertTrue(items["GD-104"]["on_sale"], "restocked GD-104 is still off sale")
        self.assertEqual(items["GD-104"]["market_qty"], 6)
        self.assertTrue(items["FD-303"]["on_sale"], "restocked FD-303 is still off sale")
        self.assertEqual(items["FD-303"]["market_qty"], 3)
        self.assertFalse(items["VC-2003"]["on_sale"])
        self.assertEqual(self.app.get("/reports/market-drift").body["items"], [])

    def test_low_stock_alerts(self):
        alerts = {a["sku"]: a["level"] for a in self.app.get("/reports/low-stock").body["items"]}
        self.assertEqual(alerts["FD-303"], "out")
        self.assertEqual(alerts["GD-104"], "low")
        self.assertNotIn("GD-101", alerts)


if __name__ == "__main__":
    unittest.main()
"""Shared fixtures for the API tests: a fresh vendor store per test."""
import json
import os
import shutil
import tempfile

from hbstock.app import build_app

FIXTURES = os.path.join(os.path.dirname(__file__), "fixtures")


def load_catalog(name="catalog_2026_10.json"):
    with open(os.path.join(FIXTURES, name), encoding="utf-8") as f:
        return json.load(f)


class VendorHome:
    def __init__(self):
        self.path = tempfile.mkdtemp(prefix="stockpush-")

    def cleanup(self):
        shutil.rmtree(self.path, ignore_errors=True)


def app_with_catalog(home, catalog):
    app = build_app(stockpush_home=home.path)
    for payload in catalog:
        resp = app.post("/products", payload)
        assert resp.status == 201, resp.body
    return app


def order(app, sku, qty=1, ship=False):
    resp = app.post("/orders", {"sku": sku, "qty": qty})
    assert resp.status == 201, resp.body
    if ship:
        assert app.post(f"/orders/{resp.body['id']}/ship").status == 200
    return resp.body["id"]
# 마켓 재고 동기화 운영 런북

## 스케줄
| 시각 | 작업 | 호출 |
|---|---|---|
| 매일 06:00 | 전체 동기화 — 모든 상품의 공지 수량을 다시 보낸다 | `POST /market/sync?full=1` |
| 10분마다 | 증분 동기화 — 바뀐 상품만 | `POST /market/sync` |
| 매일 06:20 | 대사 리포트 확인 | `GET /reports/market-drift` |

- 06:00은 오픈마켓 판매자센터의 집계일 경계다(06:00~다음 날 06:00이 하루).
- 전체 동기화가 실패하면 증분 동기화만으로는 복구되지 않는 상품이 있다. 06:30까지 재실행한다.

## 판매자센터 점검 (매주 월요일)
- 판매자 등급, 출고 지연, 판매자 귀책 취소율을 확인한다.
- 경고 내역을 확인한다. 경고 3건이 쌓이면 마켓 판매가 7일 정지된다(전 상품).
  - 출고 지연: 결제 후 3영업일 안에 출고하지 않은 주문 1건마다
  - 재입고 알림 반복: 같은 상품의 재입고 알림이 집계일 하루에 두 번 이상 나가면 1건
  - 판매자 귀책 취소: 주간 취소율 2% 초과 시 1건
- 2025-06-12 경고 2건(MKT-118). 재발하면 판매 정지까지 1건 남는 상태였다.

## 연락처
- 마켓 연동 벤더(stockpush): 벤더 포털 티켓
- 창고 실사: 물류팀 실사 담당

